package com.mindcare.auth_service.controller;
import com.mindcare.auth_service.dto.ApiResponse; import com.mindcare.auth_service.entity.PushDevice; import com.mindcare.auth_service.repository.PushDeviceRepository; import com.mindcare.auth_service.service.CurrentUserService; import jakarta.transaction.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/push-devices") @RequiredArgsConstructor
public class PushDeviceController { private final PushDeviceRepository repository; private final CurrentUserService currentUser;
 public record Upsert(@NotBlank @Size(max=120) String installationId,@NotBlank @Size(max=255) String pushToken,@Pattern(regexp="ANDROID|IOS") String platform){}
 @PutMapping @Transactional public ApiResponse<Void> upsert(@Valid @RequestBody Upsert r){var uid=currentUser.id();var byToken=repository.findByPushToken(r.pushToken());var byInstall=repository.findByUserIdAndInstallationId(uid,r.installationId());PushDevice d;if(byToken.isPresent()){d=byToken.get();if(byInstall.isPresent()&&!byInstall.get().getId().equals(d.getId())){repository.delete(byInstall.get());repository.flush();}d.claim(uid,r.installationId(),r.platform());}else if(byInstall.isPresent()){d=byInstall.get();d.refresh(r.pushToken(),r.platform());}else{d=PushDevice.create(uid,r.installationId(),r.pushToken(),r.platform());}repository.save(d);return ApiResponse.success("Đã đăng ký thiết bị",null);}
 @DeleteMapping("/{installationId}") @Transactional public ApiResponse<Void> remove(@PathVariable String installationId){repository.findByUserIdAndInstallationId(currentUser.id(),installationId).ifPresent(PushDevice::disable);return ApiResponse.success("Đã tắt push trên thiết bị",null);}
}
